try (var exec = Executors.newVirtualThreadPerTaskExecutor()) {
    for (Queue q : queues)
        exec.submit(() -> {
            while (running) {
                Message m = q.receive(idleMs);           // unmounts while blocked
                if (m == null) backoff(); else handleAndAck(m);
            }
